struct Mailbox { let name: String; let address: String }
enum Address { case mailbox(Mailbox), group([Mailbox]) }
private final class AddressParser {
    let tokens: [Token]
    var position = 0
    var error = false
    init(_ tokens: [Token]) { self.tokens = tokens }
    var peek: TokenKind? { position < tokens.count ? tokens[position].kind : nil }
    func expect(_ kind: TokenKind) -> Bool {
        if peek != kind { return false }
        position += 1; return true
    }
    func run(_ quoted: Bool) -> Range<Int> {
        let start = position
        while peek == .word || peek == .special(46) || quoted && peek == .quoted { position += 1 }
        return start..<position
    }
    func displayName(_ range: Range<Int>) -> String {
        var result = ""
        var previous = false
        for (index, token) in tokens[range].enumerated() {
            let (text, decoded, failed) = token.kind == .word ? decodeWord(token.text) : (token.text, false, false)
            error = error || failed
            if index > 0 && token.spaced && !(decoded && previous) { result += " " }
            result += text; previous = decoded
        }
        return collapseWhitespace(result)
    }
    func atom(_ range: Range<Int>) -> String? {
        if range.count % 2 == 0 { return nil }
        for (index, token) in tokens[range].enumerated() {
            if token.kind != (index % 2 == 0 ? .word : .special(46)) { return nil }
        }
        return tokens[range].map(\.text).joined()
    }
    func address(_ inGroup: Bool) -> Address? {
        let phrase = run(true)
        if peek == .special(60) {
            position += 1
            let local = run(false)
            if !expect(.special(64)) { return nil }
            let domain = run(false)
            guard expect(.special(62)), let first = atom(local), let second = atom(domain) else { return nil }
            return .mailbox(Mailbox(name: displayName(phrase), address: (first + "@" + second).lowercased()))
        }
        if peek == .special(64) {
            position += 1
            let domain = run(false)
            guard let first = atom(phrase), let second = atom(domain) else { return nil }
            return .mailbox(Mailbox(name: "", address: (first + "@" + second).lowercased()))
        }
        if peek == .special(58) && !phrase.isEmpty && !inGroup {
            position += 1
            var mailboxes: [Mailbox] = []
            if peek != .special(59) {
                while true {
                    guard let entry = address(true), case .mailbox(let mailbox) = entry else { return nil }
                    mailboxes.append(mailbox)
                    if peek != .special(44) { break }
                    position += 1
                }
            }
            if !expect(.special(59)) { return nil }
            return .group(mailboxes)
        }
        return nil
    }
}
func parseAddressList(_ value: String) -> ([Address], Bool)? {
    guard let tokens = tokenize(value, true) else { return nil }
    let parser = AddressParser(tokens)
    guard let first = parser.address(false) else { return nil }
    var addresses = [first]
    while parser.peek == .special(44) {
        parser.position += 1
        guard let next = parser.address(false) else { return nil }
        addresses.append(next)
    }
    return parser.position == tokens.count ? (addresses, parser.error) : nil
}

import Foundation

private let weekdays = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
private let months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"]
private let namedZones = ["ut": 0, "gmt": 0, "z": 0, "est": -300, "edt": -240, "cst": -360, "cdt": -300, "mst": -420, "mdt": -360, "pst": -480, "pdt": -420]
enum DateProblem: String, Error { case syntax = "bad Date syntax", range = "Date out of range", weekday = "Date weekday mismatch" }
private func leap(_ year: Int) -> Bool { year % 4 == 0 && year % 100 != 0 || year % 400 == 0 }
private func monthDays(_ year: Int, _ month: Int) -> Int { month == 2 && leap(year) ? 29 : [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1] }
private func yearDays(_ year: Int) -> Int { leap(year) ? 366 : 365 }
private func digits(_ text: String, _ lengths: [Int]) -> Bool { lengths.contains(text.utf8.count) && text.utf8.allSatisfy { 48...57 ~= $0 } }
func parseDate(_ value: String) throws -> Int {
    guard let text = removeComments(value) else { throw DateProblem.syntax }
    var tokens = splitWords(text.replacingOccurrences(of: ",", with: " , "))
    var weekday: Int?
    if tokens.count >= 3 && tokens[1] == ",", let day = weekdays.firstIndex(of: tokens[0].lowercased()) { weekday = day; tokens.removeFirst(2) }
    if tokens.count != 5 { throw DateProblem.syntax }
    let dayText = tokens[0], monthText = tokens[1], yearText = tokens[2], zone = tokens[4]
    let pieces = tokens[3].split(separator: ":", omittingEmptySubsequences: false).map(String.init)
    let numeric = (zone.first == "+" || zone.first == "-") && digits(String(zone.dropFirst()), [4])
    guard digits(dayText, [1, 2]), let monthIndex = months.firstIndex(of: monthText.lowercased()), digits(yearText, [2, 4]), [2, 3].contains(pieces.count), pieces.allSatisfy({ digits($0, [2]) }), numeric || namedZones[zone.lowercased()] != nil else { throw DateProblem.syntax }
    let month = monthIndex + 1
    let day = Int(dayText)!
    var year = Int(yearText)!
    if yearText.count == 2 { year += year < 50 ? 2000 : 1900 }
    let hour = Int(pieces[0])!, minute = Int(pieces[1])!, second = pieces.count == 3 ? Int(pieces[2])! : 0
    let offset: Int
    if numeric {
        let hours = Int(zone.dropFirst().prefix(2))!, minutes = Int(zone.suffix(2))!
        if hours > 23 || minutes > 59 { throw DateProblem.range }
        offset = (hours * 60 + minutes) * (zone.first == "-" ? -1 : 1)
    } else { offset = namedZones[zone.lowercased()]! }
    if !(1970...2099).contains(year) || day < 1 || day > monthDays(year, month) || hour > 23 || minute > 59 || second > 59 { throw DateProblem.range }
    var days = day - 1
    for current in 1970..<year { days += yearDays(current) }
    for current in 1..<month { days += monthDays(year, current) }
    let seconds = days * 86400 + hour * 3600 + minute * 60 + second - offset * 60
    if seconds < 0 { throw DateProblem.range }
    if let weekday, (days + 3) % 7 != weekday { throw DateProblem.weekday }
    return seconds
}
func formatUTC(_ seconds: Int) -> String {
    var days = seconds / 86400
    let rest = seconds % 86400
    var year = 1970
    var month = 1
    while days >= yearDays(year) { days -= yearDays(year); year += 1 }
    while days >= monthDays(year, month) { days -= monthDays(year, month); month += 1 }
    func pad(_ value: Int, _ width: Int) -> String { let text = String(value); return String(repeating: "0", count: max(0, width - text.count)) + text }
    return "\(pad(year, 4))-\(pad(month, 2))-\(pad(days + 1, 2)) \(pad(rest / 3600, 2)):\(pad(rest % 3600 / 60, 2)):\(pad(rest % 60, 2))"
}

import Foundation

struct Header {
    var fields: [(String, String)] = []
    var invalidLines: [Int] = []
    func value(_ name: String) -> String? { fields.first { $0.0 == name.lowercased() }?.1 }
    func count(_ name: String) -> Int { fields.filter { $0.0 == name.lowercased() }.count }
}
enum TokenKind: Equatable { case word, quoted, special(UInt8) }
struct Token { let kind: TokenKind; let text: String; let spaced: Bool }
func splitWords(_ text: String) -> [String] { text.split { $0 == " " || $0 == "\t" }.map(String.init) }
func collapseWhitespace(_ text: String) -> String { splitWords(text).joined(separator: " ") }
func stripWhitespace(_ text: String) -> String { String(text.drop(while: { $0 == " " || $0 == "\t" }).reversed().drop(while: { $0 == " " || $0 == "\t" }).reversed()) }
func stripTrailing(_ text: String) -> String { String(text.reversed().drop(while: { $0 == " " || $0 == "\t" }).reversed()) }
func parseFields(_ lines: [(Int, String)]) -> Header {
    var header = Header()
    var inField = false
    for (number, text) in lines {
        if text.first == " " || text.first == "\t" {
            if inField { header.fields[header.fields.count - 1].1 += text } else { header.invalidLines.append(number) }
            continue
        }
        inField = false
        if let split = text.firstIndex(of: ":") {
            let name = String(text[..<split])
            if !name.isEmpty && name.utf8.allSatisfy({ 33...126 ~= $0 }) {
                header.fields.append((name.lowercased(), String(text[text.index(after: split)...])))
                inField = true
            }
        }
        if !inField { header.invalidLines.append(number) }
    }
    header.fields = header.fields.map { ($0.0, stripWhitespace($0.1)) }
    return header
}
func removeComments(_ text: String) -> String? {
    var result: [UInt8] = []
    var depth = 0
    var escaped = false
    for byte in text.utf8 {
        if depth == 0 {
            if byte == 40 { depth = 1; result.append(32) } else { result.append(byte) }
        } else if escaped { escaped = false }
        else if byte == 92 { escaped = true }
        else if byte == 40 { depth += 1 }
        else if byte == 41 { depth -= 1 }
    }
    return depth == 0 ? String(decoding: result, as: UTF8.self) : nil
}
func wordByte(_ byte: UInt8, _ address: Bool) -> Bool {
    if address { return 65...90 ~= byte || 97...122 ~= byte || 48...57 ~= byte || "!#$%&'*+-/=?^_`{|}~".utf8.contains(byte) }
    return 33...126 ~= byte && !"()<>@,;:\\\"/[]?=".utf8.contains(byte)
}
func tokenize(_ text: String, _ address: Bool) -> [Token]? {
    let data = Array(text.utf8)
    let specials = Array((address ? "<>:;@,." : "/;=").utf8)
    var tokens: [Token] = []
    var position = 0
    var spaced = false
    while position < data.count {
        let byte = data[position]
        if byte == 32 || byte == 9 { spaced = true; position += 1; continue }
        if byte == 40 {
            var depth = 1
            position += 1
            while position < data.count && depth > 0 {
                if data[position] == 92 { position += 2; continue }
                if data[position] == 40 { depth += 1 } else if data[position] == 41 { depth -= 1 }
                position += 1
            }
            if depth != 0 { return nil }
            spaced = true; continue
        }
        if byte == 34 {
            position += 1
            var value: [UInt8] = []
            while position < data.count && data[position] != 34 {
                if data[position] == 92 { position += 1 }
                if position >= data.count { return nil }
                value.append(data[position]); position += 1
            }
            if position == data.count { return nil }
            position += 1
            tokens.append(Token(kind: .quoted, text: String(decoding: value, as: UTF8.self), spaced: spaced))
        } else if specials.contains(byte) {
            tokens.append(Token(kind: .special(byte), text: String(decoding: [byte], as: UTF8.self), spaced: spaced)); position += 1
        } else if wordByte(byte, address) {
            let start = position
            while position < data.count && wordByte(data[position], address) { position += 1 }
            tokens.append(Token(kind: .word, text: String(decoding: data[start..<position], as: UTF8.self), spaced: spaced))
        } else { return nil }
        spaced = false
    }
    return tokens
}
func decodeWord(_ word: String) -> (String, Bool, Bool) {
    if word.utf8.count < 4 || !word.hasPrefix("=?") || !word.hasSuffix("?=") { return (word, false, false) }
    let pieces = word.dropFirst(2).dropLast(2).split(separator: "?", omittingEmptySubsequences: false).map(String.init)
    if pieces.count != 3 || pieces.contains("") { return (word, false, false) }
    func decode() -> String? {
        if pieces[0].lowercased() != "us-ascii" { return nil }
        let data: [UInt8]
        if ["B", "b"].contains(pieces[1]) {
            guard let decoded = strictBase64(pieces[2]) else { return nil }
            data = decoded
        } else if ["Q", "q"].contains(pieces[1]) {
            let bytes = Array(pieces[2].utf8)
            var result: [UInt8] = []
            var position = 0
            while position < bytes.count {
                switch bytes[position] {
                case 95: result.append(32); position += 1
                case 61:
                    guard let value = hexByte(bytes, position + 1) else { return nil }
                    result.append(value); position += 3
                default: result.append(bytes[position]); position += 1
                }
            }
            data = result
        } else { return nil }
        return data.allSatisfy { 32...126 ~= $0 } ? String(decoding: data, as: UTF8.self) : nil
    }
    if let result = decode() { return (result, true, false) }
    return (word, false, true)
}
func decodeUnstructured(_ value: String) -> (String, Bool) {
    var result = ""
    var previous = false
    var error = false
    for (index, word) in splitWords(value).enumerated() {
        let (text, decoded, failed) = decodeWord(word)
        if index > 0 && !(decoded && previous) { result += " " }
        result += text; previous = decoded; error = error || failed
    }
    return (collapseWhitespace(result), error)
}
struct Parameters { let mainType: String; let subtype: String; let values: [String: String] }
func parseParameters(_ value: String, _ withSubtype: Bool) -> Parameters? {
    guard let tokens = tokenize(value, false), tokens.first?.kind == .word else { return nil }
    var subtype = ""
    var position = 1
    if withSubtype {
        if tokens.count < 3 || tokens[1].kind != .special(47) || tokens[2].kind != .word { return nil }
        subtype = tokens[2].text.lowercased(); position = 3
    }
    var parameters: [String: String] = [:]
    while position < tokens.count {
        if position + 4 > tokens.count || tokens[position].kind != .special(59) || tokens[position + 1].kind != .word || tokens[position + 2].kind != .special(61) || ![TokenKind.word, .quoted].contains(tokens[position + 3].kind) { return nil }
        let name = tokens[position + 1].text.lowercased()
        if parameters[name] == nil { parameters[name] = tokens[position + 3].text }
        position += 4
    }
    return Parameters(mainType: tokens[0].text.lowercased(), subtype: subtype, values: parameters)
}

import Foundation

let checkedFields = ["From", "To", "Cc", "Subject", "Date", "Message-ID", "In-Reply-To", "References", "MIME-Version", "Content-Type", "Content-Transfer-Encoding", "Content-Disposition"]
typealias MailLine = (Int, String)
func readLines(_ path: String) throws -> [String] {
    var lines = try String(contentsOfFile: path, encoding: .utf8).components(separatedBy: "\n")
    if lines.last == "" { lines.removeLast() }
    return lines
}
func readMailbox(_ lines: [String]) -> [[MailLine]] {
    var messages: [[MailLine]] = []
    for (number, line) in lines.enumerated() {
        if line.hasPrefix("From ") { messages.append([]) }
        else if !messages.isEmpty {
            let unquoted = line.drop(while: { $0 == ">" })
            let text = unquoted.count < line.count && unquoted.hasPrefix("From ") ? String(line.dropFirst()) : line
            messages[messages.count - 1].append((number + 1, text))
        }
    }
    for index in messages.indices where messages[index].last?.1 == "" { messages[index].removeLast() }
    return messages
}
func splitSections(_ lines: [MailLine]) -> ([MailLine], [MailLine]) {
    if let index = lines.firstIndex(where: { $0.1.isEmpty }) { return (Array(lines[..<index]), Array(lines[(index + 1)...])) }
    return (lines, [])
}
func isMessageID(_ text: String) -> Bool {
    if text.utf8.count < 3 || !text.hasPrefix("<") || !text.hasSuffix(">") { return false }
    let inside = text.dropFirst().dropLast()
    return inside.utf8.filter { $0 == 64 }.count == 1 && inside.first != "@" && inside.last != "@" && inside.utf8.allSatisfy { 33...126 ~= $0 && !"<>()\"\\".utf8.contains($0) }
}
func extractIDs(_ value: String) -> [String] {
    let data = Array(value.utf8)
    var result: [String] = []
    var position = 0
    while position < data.count {
        guard let start = data[position...].firstIndex(of: 60), let end = data[(start + 1)...].firstIndex(of: 62) else { break }
        let id = String(decoding: data[start...end], as: UTF8.self)
        if isMessageID(id) { result.append(id) }
        position = end + 1
    }
    return result
}
func dateNotation(_ seconds: Int?) -> String { seconds.map(formatUTC) ?? "invalid" }
func subjectNotation(_ subject: String) -> String { subject.isEmpty ? "(no subject)" : subject }
func asciiLess(_ first: String, _ second: String) -> Bool { first.utf8.lexicographicallyPrecedes(second.utf8) }
final class Entity {
    let number: String
    var mainType = "text"
    var subtype = "plain"
    var parameters: [String: String] = [:]
    var disposition: String?
    var filename = ""
    var children: [Entity]?
    var content = ""
    init(_ number: String) { self.number = number }
    func parameter(_ name: String) -> String { parameters[name] ?? "" }
}
final class Message {
    let number: Int
    var problems: [String] = []
    var sender: Mailbox?
    var to: [String] = []
    var cc: [String] = []
    var subject = ""
    var baseSubject = ""
    var reply = false
    var date: Int?
    var id = ""
    var references: [String] = []
    var body = Entity("1")
    var thread = 0
    var depth = 0
    var parent: Message?
    var sortKey: (Int, Int, String, Int) { (date == nil ? 1 : 0, date ?? 0, id, number) }
    init(_ number: Int) { self.number = number }
    func process(_ lines: [MailLine], _ knownIDs: inout [String: Int]) {
        let (headerLines, bodyLines) = splitSections(lines)
        let header = parseFields(headerLines)
        for number in header.invalidLines { problems.append("bad header line \(number)") }
        for name in checkedFields where header.count(name) > 1 { problems.append("duplicate " + name) }
        readSender(header.value("From"))
        to = readRecipients(header.value("To"), "To")
        cc = readRecipients(header.value("Cc"), "Cc")
        let (subject, error) = decodeUnstructured(header.value("Subject") ?? "")
        self.subject = subject
        if error { problems.append("bad encoded word in Subject") }
        var base = subject
        while base.prefix(3).lowercased() == "re:" { base = String(base.dropFirst(3).drop(while: { $0 == " " })); reply = true }
        baseSubject = base
        if let value = header.value("Date") {
            do { date = try parseDate(value) }
            catch let error as DateProblem { problems.append(error.rawValue) }
            catch { preconditionFailure() }
        } else { problems.append("missing Date") }
        if let value = header.value("Message-ID") {
            if !isMessageID(value) { problems.append("bad Message-ID") }
            else if let number = knownIDs[value] { problems.append("Message-ID already used by message \(number)") }
            else { id = value; knownIDs[value] = number }
        } else { problems.append("missing Message-ID") }
        references = extractIDs(header.value("References") ?? "")
        if let first = extractIDs(header.value("In-Reply-To") ?? "").first, references.last != first { references.append(first) }
        var enabled = false
        if let value = header.value("MIME-Version") {
            if let text = removeComments(value), text.filter({ $0 != " " && $0 != "\t" }) == "1.0" { enabled = true }
            else { problems.append("bad MIME-Version") }
        }
        body = parseEntity("1", header, bodyLines, enabled)
    }
    func readSender(_ value: String?) {
        guard let value else { problems.append("missing From"); return }
        if let (addresses, error) = parseAddressList(value), addresses.count == 1, case .mailbox(let mailbox) = addresses[0] {
            sender = mailbox
            if error { problems.append("bad encoded word in From") }
        } else { problems.append("bad From") }
    }
    func readRecipients(_ value: String?, _ name: String) -> [String] {
        guard let value else { return [] }
        guard let (addresses, error) = parseAddressList(value) else { problems.append("bad " + name); return [] }
        var recipients: [String] = []
        for address in addresses {
            switch address { case .mailbox(let mailbox): recipients.append(mailbox.address); case .group(let mailboxes): recipients += mailboxes.map(\.address) }
        }
        if error { problems.append("bad encoded word in " + name) }
        return recipients
    }
    func parseEntity(_ number: String, _ header: Header, _ lines: [MailLine], _ enabled: Bool) -> Entity {
        let entity = Entity(number)
        if enabled {
            if let value = header.value("Content-Type") {
                if let parsed = parseParameters(value, true) { entity.mainType = parsed.mainType; entity.subtype = parsed.subtype; entity.parameters = parsed.values }
                else { problems.append("bad Content-Type in part " + number) }
            }
            if let value = header.value("Content-Disposition") {
                if let parsed = parseParameters(value, false) { entity.disposition = parsed.mainType; entity.filename = parsed.values["filename"] ?? "" }
                else { problems.append("bad Content-Disposition in part " + number) }
            }
        }
        if entity.filename.isEmpty { entity.filename = entity.parameter("name") }
        if entity.mainType == "text", let charset = entity.parameters["charset"], charset.lowercased() != "us-ascii" { problems.append("unsupported charset \"\(charset.lowercased())\" in part \(number)") }
        if enabled && entity.mainType == "multipart" {
            let boundary = entity.parameter("boundary")
            if !boundary.isEmpty { splitMultipart(entity, lines, boundary); return entity }
            problems.append("missing boundary in part " + number)
        }
        let original = lines.map { $0.1 }.joined(separator: "\n")
        let encoding = enabled ? (header.value("Content-Transfer-Encoding") ?? "7bit").lowercased() : "7bit"
        switch encoding {
        case "base64":
            if let content = decodeBase64Body(original) { entity.content = content }
            else { problems.append("bad base64 in part " + number) }
        case "quoted-printable":
            let (content, error) = decodeQuotedPrintable(original)
            entity.content = content
            if error { problems.append("bad quoted-printable in part " + number) }
        default:
            entity.content = original
            if !["7bit", "8bit", "binary"].contains(encoding) { problems.append("unknown encoding \"\(encoding)\" in part \(number)") }
        }
        return entity
    }
    func splitMultipart(_ entity: Entity, _ lines: [MailLine], _ boundary: String) {
        var parts: [[MailLine]] = []
        var closed = false
        for line in lines {
            let text = stripTrailing(line.1)
            if text == "--" + boundary + "--" { closed = true; break }
            if text == "--" + boundary { parts.append([]) }
            else if !parts.isEmpty { parts[parts.count - 1].append(line) }
        }
        if parts.isEmpty { problems.append("no parts in part " + entity.number) }
        else if !closed { problems.append("unterminated multipart in part " + entity.number) }
        var children: [Entity] = []
        for (index, part) in parts.enumerated() {
            let (headerLines, bodyLines) = splitSections(part)
            let header = parseFields(headerLines)
            for number in header.invalidLines { problems.append("bad header line \(number)") }
            children.append(parseEntity("\(entity.number).\(index + 1)", header, bodyLines, true))
        }
        entity.children = children
    }
}
func collectTextParts(_ entity: Entity, _ allowHTML: Bool) -> [Entity] {
    guard let children = entity.children else {
        if entity.disposition == "attachment" || entity.mainType != "text" { return [] }
        return entity.subtype == "plain" || entity.subtype == "html" && allowHTML ? [entity] : []
    }
    if entity.subtype == "alternative" {
        for pass in [false, true] { for child in children { let parts = collectTextParts(child, pass); if !parts.isEmpty { return parts } } }
        return []
    }
    return children.flatMap { collectTextParts($0, allowHTML) }
}
func quotePrefix(_ depth: Int) -> String { depth == 0 ? "" : String(repeating: ">", count: depth) + " " }
func wrap(_ text: String, _ prefix: String) -> [String] {
    var lines: [String] = []
    var current = ""
    for word in splitWords(text) {
        if !current.isEmpty && current.utf8.count + 1 + word.utf8.count > 72 { lines.append(prefix + current); current = word }
        else { if !current.isEmpty { current += " " }; current += word }
    }
    lines.append(prefix + current)
    return lines
}
struct LogicalLine { let depth: Int; var text: String; var flowing = false }
func flowedLines(_ content: String, _ deleteSpace: Bool) -> [String] {
    if content.isEmpty { return [] }
    var logical: [LogicalLine] = []
    for line in content.split(separator: "\n", omittingEmptySubsequences: false) {
        let remainder = line.drop(while: { $0 == ">" })
        let depth = line.count - remainder.count
        let text = remainder.hasPrefix(" ") ? String(remainder.dropFirst()) : String(remainder)
        let flowing = text.hasSuffix(" ") && text != "-- "
        if let previous = logical.last, previous.flowing && previous.depth == depth {
            let last = logical.count - 1
            if deleteSpace { logical[last].text.removeLast() }
            logical[last].text += text; logical[last].flowing = flowing
        } else { logical.append(LogicalLine(depth: depth, text: text, flowing: flowing)) }
    }
    return logical.flatMap { wrap($0.text, quotePrefix($0.depth)) }
}
func referenceValue(_ name: String) -> String? {
    let named = ["amp": "&", "lt": "<", "gt": ">", "quot": "\"", "apos": "'", "nbsp": " "]
    if let value = named[name] { return value }
