    return String(decoding: result, as: UTF8.self)
}
func decodeQuotedPrintable(_ text: String) -> (String, Bool) {
    let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
    var result: [UInt8] = []
    var error = false
    for (index, line) in lines.enumerated() {
        var data = Array(line.utf8)
        while let byte = data.last, byte == 32 || byte == 9 { data.removeLast() }
        let soft = data.last == 61
        if soft { data.removeLast() }
        var position = 0
        while position < data.count {
            if data[position] == 61 {
                if let value = hexByte(data, position + 1), value == 9 || 32...126 ~= value { result.append(value); position += 3; continue }
                error = true
            }
            result.append(data[position]); position += 1
        }
        if !soft && index + 1 < lines.count { result.append(10) }
    }
    return (String(decoding: result, as: UTF8.self), error)
}

final class Container {
    let id: String
    var message: Message?
    weak var parent: Container?
    var children: [Container] = []
    var subject: String?
    init(_ id: String) { self.id = id }
    func ancestorOrSelf(_ other: Container) -> Bool {
        var current: Container? = other
        while let node = current { if node === self { return true }; current = node.parent }
        return false
    }
}
private func adopt(_ parent: Container, _ child: Container) { child.parent = parent; parent.children.append(child) }
private func prune(_ containers: [Container], _ atRoot: Bool) -> [Container] {
